import copy
import unittest

from flatten import flatten


class FlattenTest(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(flatten([]), [])

    def test_already_flat(self):
        self.assertEqual(flatten([1, 2, 3]), [1, 2, 3])

    def test_nested(self):
        self.assertEqual(flatten([1, [2, [3, [4]], 5], 6]), [1, 2, 3, 4, 5, 6])

    def test_empty_nested_lists(self):
        self.assertEqual(flatten([[], [[]], [1, []], 2]), [1, 2])

    def test_non_lists_kept(self):
        d = {"a": [1]}
        items = [(1, 2), "abc", d, [b"xy", {3}], None]
        self.assertEqual(flatten(items), [(1, 2), "abc", d, b"xy", {3}, None])

    def test_tuple_containing_list_not_expanded(self):
        t = ([1, 2],)
        self.assertEqual(flatten([t]), [t])

    def test_returns_new_list(self):
        data = [1, 2]
        result = flatten(data)
        self.assertEqual(result, data)
        self.assertIsNot(result, data)

    def test_does_not_mutate(self):
        data = [1, [2, [3]], [[4]]]
        before = copy.deepcopy(data)
        flatten(data)
        self.assertEqual(data, before)

    def test_deep_nesting(self):
        data = [0]
        for i in range(1, 5000):
            data = [data, i]
        self.assertEqual(flatten(data), list(range(5000)))

    def test_order_preserved(self):
        self.assertEqual(flatten([[3, 1], 2, [[0]]]), [3, 1, 2, 0])


if __name__ == "__main__":
    unittest.main()
